def _merge_tags(existing: str, new: str) -> str:
    parts: list[str] = []
    seen: set[str] = set()
    for blob in (existing, new):
        for p in blob.split(";"):
            p = p.strip()
            if p and p not in seen:
                seen.add(p)
                parts.append(p)
    return ";".join(parts)


def apply_batch(batch_name: str, *, dry_run: bool = False) -> int:
    batch = BATCHES.get(batch_name)
    if not batch:
        print(f"Unknown batch: {batch_name}", file=sys.stderr)
        return 1

    with CSV_PATH.open(encoding="utf-8-sig", newline="") as f:
        reader = csv.DictReader(f)
        fieldnames = reader.fieldnames
        if not fieldnames:
            print("CSV has no header", file=sys.stderr)
            return 1
        rows = list(reader)

    updated: list[str] = []
    for row in rows:
        term = (row.get("term") or "").strip()
        if term not in batch:
            continue
        patch = batch[term]
        for col in UPDATABLE_COLUMNS:
            if col not in patch:
                continue
            if col == "tags":
                row[col] = _merge_tags(row.get("tags") or "", patch[col])
            else:
                row[col] = patch[col]
        updated.append(term)

    missing = sorted(set(batch) - set(updated))
    if missing:
        print(f"Terms not found in CSV: {', '.join(missing)}", file=sys.stderr)
        return 1

    if dry_run:
        print(f"[dry-run] Would update: {', '.join(updated)}")
        return 0

    with CSV_PATH.open("w", encoding="utf-8-sig", newline="") as f:
        writer = csv.DictWriter(f, fieldnames=fieldnames, lineterminator="\n")
        writer.writeheader()
        writer.writerows(rows)

    print(f"Updated {len(updated)} terms: {', '.join(updated)}")
    return 0


def main() -> int:
    ap = argparse.ArgumentParser(description="用語ゼロ書き直しデータをCSVに適用")
    ap.add_argument("--batch", required=True, help="バッチ名（例: batch_a_cluster1）")
    ap.add_argument("--dry-run", action="store_true")
    args = ap.parse_args()
    return apply_batch(args.batch, dry_run=args.dry_run)


if __name__ == "__main__":
    raise SystemExit(main())
